package com.yuanqi.app.photo.controller;
import com.yuanqi.app.common.api.PageResult;import com.yuanqi.app.common.api.Result;import com.yuanqi.app.common.context.UserContext;import com.yuanqi.app.photo.service.PublicPhotoService;import com.yuanqi.app.photo.vo.PublicPhotoViews;import io.swagger.v3.oas.annotations.Operation;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/v1/photos") public class PublicPhotoController{private final PublicPhotoService service;public PublicPhotoController(PublicPhotoService s){service=s;}@Operation(summary="公开作品 Feed；稳定页码排序并强制公开状态过滤")@GetMapping public Result<PageResult<PublicPhotoViews.Card>> feed(@RequestParam(required=false)String keyword,@RequestParam(required=false)String categoryId,@RequestParam(required=false,name="tagId")List<String>tagIds,@RequestParam(defaultValue="1")int page){return Result.success(service.feed(UserContext.getUserId(),keyword,categoryId,tagIds,page));}@Operation(summary="公开作品详情；不混入作者草稿")@GetMapping("/{workId}")public Result<PublicPhotoViews.Detail> detail(@PathVariable String workId){return Result.success(service.detail(UserContext.getUserId(),workId));}}
